preConditionHook:
// SWING REGRESSION TREND (Brian's notes I3, TRIAGE I3, p. 3), a pane-2 filter.
// Least-squares lines through the X most recent 1-bar swing highs and the X most
// recent swing lows; their FORWARD slopes (-sxy/sxx on the bars-ago axis), in
// price per bar, are compared with s ATR per bar. Both at least +s: uptrend,
// LONG. Both at most -s: downtrend, SHORT. Anything else is a range, true on
// neither side -- negating ONE side admits the other trend, so a range placement
// needs both sides negated. Not ThreePushSlopeBias (the sign of a line through a
// pattern's own pivots) nor TrendLineSlopeFlattening (two-pivot slopes): neither
// regresses N pivots per side.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// THE SWING-POINT REGRESSION, shared verbatim by FractalTrendlineBreak and
// SwingRegressionTrend. Ordinary least squares of pivot PRICE on pivot BARS-AGO
// over the nFit most recent confirmed pivots of each side. No arrays (the word is
// unregistered), so the pivots are not stored: pass 1 scans for them and sums
// x and y to get the means, pass 2 re-runs the identical scan and accumulates the
// CENTRED sums sxx, sxy, syy. Centring makes the slope and R^2 depend on price
// differences only (the shift test). Both passes sum NEWEST-FIRST, in scan order,
// and the twin's statements are the same statements in the same order, so the two
// sums are the same doubles. On the bars-ago axis a slope sxy/sxx > 0 means the
// line was HIGHER in the past, i.e. it FALLS going forward. nFit < 2 never fits.
//
// PIVOT SCAN, hand-rolled in BOTH twins (SwingPivotTarget's open-coded form):
// more than two occurrences are needed and Occurrence 3+ of SwingHigh/SwingLow is
// UNMEASURED, so no SwingHigh(n, ...) call stands in. MEASURED test
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT OR
// BEYOND the `strength` OLDER bars and STRICTLY BEYOND the `strength` NEWER bars
// (bars-ago indexing: the newer bars are the smaller pk, el_gt / el_lt; the older
// el_ge / el_le), confirmation lag exactly `strength` bars, candidate offsets
// strength..window-1, the neighbourhood reaching `strength` bars past the window.
// Swings are non-alternating: highs and lows are two independent series.
// No early break, matching the twin (Break is not a registered word).
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingPointTestHolds's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;), because EL
// evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
pS = (int)strength;
pW = (int)pivotLookback;
nFit = (int)X;
nH = 0;
nL = 0;
sxH = 0.0;
syH = 0.0;
sxL = 0.0;
syL = 0.0;
hBarNew = -1;
lBarNew = -1;
for (pj = pS; pj <= pW - 1; ++pj) {
    okHi = true;
    okLo = true;
    for (pk = pj - pS; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) okHi = false;
        if (!el_lt(low[pj], low[pk])) okLo = false;
    }
    for (pk = pj + 1; pk <= pj + pS; ++pk) {
        if (!el_ge(high[pj], high[pk])) okHi = false;
        if (!el_le(low[pj], low[pk])) okLo = false;
    }
    if (okHi && nH < nFit) {
        nH = nH + 1;
        if (nH == 1) hBarNew = pj;
        sxH = sxH + pj;
        syH = syH + high[pj];
    }
    if (okLo && nL < nFit) {
        nL = nL + 1;
        if (nL == 1) lBarNew = pj;
        sxL = sxL + pj;
        syL = syL + low[pj];
    }
}
haveH = (nFit >= 2) && (nH >= nFit);
haveL = (nFit >= 2) && (nL >= nFit);
mxH = 0.0;
myH = 0.0;
mxL = 0.0;
myL = 0.0;
if (haveH) {
    mxH = sxH / nH;
    myH = syH / nH;
}
if (haveL) {
    mxL = sxL / nL;
    myL = syL / nL;
}
cH = 0;
cL = 0;
sxxH = 0.0;
sxyH = 0.0;
syyH = 0.0;
sxxL = 0.0;
sxyL = 0.0;
syyL = 0.0;
for (pj = pS; pj <= pW - 1; ++pj) {
    okHi = true;
    okLo = true;
    for (pk = pj - pS; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) okHi = false;
        if (!el_lt(low[pj], low[pk])) okLo = false;
    }
    for (pk = pj + 1; pk <= pj + pS; ++pk) {
        if (!el_ge(high[pj], high[pk])) okHi = false;
        if (!el_le(low[pj], low[pk])) okLo = false;
    }
    if (okHi && cH < nFit) {
        cH = cH + 1;
        dxH = pj - mxH;
        dyH = high[pj] - myH;
        sxxH = sxxH + dxH * dxH;
        sxyH = sxyH + dxH * dyH;
        syyH = syyH + dyH * dyH;
    }
    if (okLo && cL < nFit) {
        cL = cL + 1;
        dxL = pj - mxL;
        dyL = low[pj] - myL;
        sxxL = sxxL + dxL * dxL;
        sxyL = sxyL + dxL * dyL;
        syyL = syyL + dyL * dyL;
    }
}
fitH = haveH && el_gt(sxxH, 0.0);
fitL = haveL && el_gt(sxxL, 0.0);
slopeH = 0.0;
slopeL = 0.0;
if (fitH) slopeH = -sxyH / sxxH;
if (fitL) slopeL = -sxyL / sxxL;
